import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const o="data:image/svg+xml;base64,",l="/assets/alias-objekt-dialog.CW0nxBT1.png",n="data:image/svg+xml;base64,",I="/assets/objektbaum-effekt-auswahl.DAp8mqRq.png",C=JSON.parse('{"title":"Controlling the device for the first time","description":"","frontmatter":{"order":3,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/01.erste-schritte/03.erste-steuerung.md"},"headers":[],"relativePath":"adapter/wled/erste-schritte/erste-steuerung.md","filePath":"adapter/wled/erste-schritte/erste-steuerung.md","lastUpdated":null}'),d={name:"adapter/wled/erste-schritte/erste-steuerung.md"};function h(r,e,g,c,p,m){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="controlling-the-device-for-the-first-time" tabindex="-1">Controlling the device for the first time <a class="header-anchor" href="#controlling-the-device-for-the-first-time" aria-label="Permalink to &quot;Controlling the device for the first time&quot;">​</a></h1><p><a id="state-use-switch-off-whole"></a></p><h2 id="which-state-do-i-use-to-switch-on-and-off-the-whole-device-or-just-a-segment" tabindex="-1">Which state do I use to switch on and off, the whole device or just a segment? <a class="header-anchor" href="#which-state-do-i-use-to-switch-on-and-off-the-whole-device-or-just-a-segment" aria-label="Permalink to &quot;Which state do I use to switch on and off, the whole device or just a segment?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="use-brightness-percent-0-100"></a></p><h2 id="how-do-i-use-brightness-as-a-percentage-0-to-100-for-example-for-alexa" tabindex="-1">How do I use brightness as a percentage (0 to 100), for example for Alexa? <a class="header-anchor" href="#how-do-i-use-brightness-as-a-percentage-0-to-100-for-example-for-alexa" aria-label="Permalink to &quot;How do I use brightness as a percentage (0 to 100), for example for Alexa?&quot;">​</a></h2><p><strong>In short:</strong> Like WLED itself, <code>bri</code> works with values from 0 to 255, not with percentages. For 0 to 100 % you create an alias on <code>bri</code> that divides by 2.55 when reading and multiplies by 2.55 when writing.</p><p><strong>From v0.10.0:</strong> The adapter provides the percentage values itself. <code>wled.0.&lt;device&gt;.light.dimmer</code> holds the overall brightness in percent (0 to 100 %, role <code>level.dimmer</code>). If you write a value there, the adapter converts it to <code>bri</code>, and from 1 % upwards it also switches the light on (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/328" target="_blank" rel="noreferrer">#328</a>). You then only need the alias below for special cases, for example for the brightness of a single segment.</p><p>The adapter doesn&#39;t switch <code>bri</code> to percent, because 255 steps are finer and a switch would break existing scripts and visualisations. The state has the role <code>level.brightness</code> with a minimum of 0 and a maximum of 255. This applies to the overall brightness <code>wled.0.&lt;device&gt;.bri</code> and in the same way to the segment brightness <code>wled.0.&lt;device&gt;.seg.&lt;segment&gt;.bri</code>.</p><p><img src="'+o+`" alt="Diagram: A percentage alias from 0 to 100 % converts to bri from 0 to 255 with Math.ceil(val * 2.55) when writing, and back with Math.round(val / 2.55) when reading."></p><h3 id="do-you-need-a-conversion-at-all" tabindex="-1">Do you need a conversion at all? <a class="header-anchor" href="#do-you-need-a-conversion-at-all" aria-label="Permalink to &quot;Do you need a conversion at all?&quot;">​</a></h3><p>For Alexa and Google Home via the iot adapter, usually not: because <code>bri</code> comes with a minimum and a maximum, the iot adapter can convert a percentage to 0 to 255 by itself. You need the alias if you want to see or write percentages in VIS, in scripts or in another integration, or if the conversion in the iot adapter doesn&#39;t work for you.</p><h3 id="how-to-create-a-percentage-alias" tabindex="-1">How to create a percentage alias <a class="header-anchor" href="#how-to-create-a-percentage-alias" aria-label="Permalink to &quot;How to create a percentage alias&quot;">​</a></h3><ol><li>In Admin, open the &quot;Objects&quot; tab and create a state under <code>alias.0</code>, for example <code>alias.0.WLED.LivingRoom.brightness</code>.</li><li>Give it the type <code>number</code>, the role <code>level.dimmer</code>, minimum <code>0</code>, maximum <code>100</code> and the unit <code>%</code>.</li><li>Open the state with the pencil (&quot;Edit object&quot;) and switch to the &quot;Alias&quot; tab. Under &quot;Alias state ID&quot;, enter the WLED state: <code>wled.0.&lt;device&gt;.bri</code>.</li><li>Tick &quot;Use convert functions&quot; and enter the conversion. &quot;Read converter&quot;: <code>Math.round(val / 2.55)</code>. &quot;Write converter&quot;: <code>Math.ceil(val * 2.55)</code>.</li><li>Save, and set the alias to <code>50</code> as a test. <code>bri</code> should then jump to <code>128</code>, and the strip lights up at half brightness.</li></ol><p>In the object, the alias part looks like this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;common&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Brightness living room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;number&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;level.dimmer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;min&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;max&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;unit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;alias&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wled.0.&lt;device&gt;.bri&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Math.round(val / 2.55)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Math.ceil(val * 2.55)&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><img src="`+l+'" alt="Admin 8.3, dialog &quot;Edit object: alias.0.WLED.LivingRoom.brightness&quot;, &quot;Alias&quot; tab: alias state ID wled.0.MAC.bri, &quot;Use convert functions&quot; ticked, read converter Math.round(val / 2.55), write converter Math.ceil(val * 2.55)."></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Round up when writing (<code>Math.ceil</code>). Otherwise 1 % becomes the value 0 and the light turns off, even though you only wanted it very dim.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Don&#39;t build the conversion with two scripts that trigger each other (the percentage state writes <code>bri</code>, <code>bri</code> writes the percentage state). Because of the rounding, the two values can jump back and forth. An alias doesn&#39;t have this problem, because there is only one real value.</p></div><p><strong>See also:</strong> <a href="./../anleitungen/vis-und-smarthome#connect-wled-iot-adapter-switch">How do I connect WLED to the iot adapter and switch effects, presets and color via Alexa or Google Home?</a></p><p><a id="choose-effect-palette"></a></p><h2 id="where-do-i-choose-the-effect-and-the-palette" tabindex="-1">Where do I choose the effect and the palette? <a class="header-anchor" href="#where-do-i-choose-the-effect-and-the-palette" aria-label="Permalink to &quot;Where do I choose the effect and the palette?&quot;">​</a></h2><p><strong>In short:</strong> You set the effect and the palette per segment: <code>wled.0.&lt;device&gt;.seg.&lt;segment&gt;.fx</code> for the effect and <code>wled.0.&lt;device&gt;.seg.&lt;segment&gt;.pal</code> for the palette. Both states have a drop-down list with the names your WLED device reports.</p><p>The first segment has the number <code>0</code>. If you have created several segments in WLED, each one has its own <code>fx</code> and <code>pal</code> states. What gets stored is the number of the effect or palette; the drop-down list shows the matching name.</p><p><img src="'+n+'" alt="Diagram: In the object tree, on, bri and ps sit directly under the device, and fx, pal, sx, ix and col under each segment seg.0, seg.1 and so on. fx and pal have a drop-down list with the number and name from the device."></p><h3 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h3><ol><li>In Admin, open the &quot;Objects&quot; tab and go to <code>wled.0.&lt;device&gt;.seg.0</code>.</li><li>Click the value of the <code>fx</code> state. A list with the effect names of your device opens. Pick one.</li><li>Do the same with <code>pal</code> for the palette.</li><li>The strip changes right away. The state then holds the number of the selected entry.</li></ol><p>The effect also uses <code>seg.&lt;segment&gt;.sx</code> (speed) and <code>seg.&lt;segment&gt;.ix</code> (intensity).</p><p><img src="'+I+'" alt="Admin 8.3, &quot;Objects&quot; tab: under wled.0.MAC.seg.0 the &quot;Write value&quot; dialog for fx is open, and the drop-down list shows the device&#39;s effect names (Solid, Blink, Breathe and so on). The &quot;Value&quot; column shows Solid(0)."></p><p>In a script you write the number, for example <code>setState(&#39;wled.0.&lt;device&gt;.seg.0.fx&#39;, 9)</code>. Which number belongs to which name is listed in the drop-down list in the object (<code>common.states</code>).</p><h3 id="new-effects-are-missing-from-the-list-after-a-firmware-update" tabindex="-1">New effects are missing from the list after a firmware update <a class="header-anchor" href="#new-effects-are-missing-from-the-list-after-a-firmware-update" aria-label="Permalink to &quot;New effects are missing from the list after a firmware update&quot;">​</a></h3><p>The adapter reads the names from the device, so the list depends on your WLED firmware.</p><p><strong>Up to v0.9.2:</strong> The adapter sets the drop-down list only once per adapter run. Effects and palettes added by a firmware update only appear after you restart the adapter instance.</p><p><strong>From v0.9.3:</strong> The adapter rewrites the lists every time it connects to the device. Because WLED restarts during a firmware update and then reconnects, new effects appear without restarting the adapter (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/912" target="_blank" rel="noreferrer">#912</a>).</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If the drop-down list is missing completely or out of date, restart the <code>wled.0</code> instance once. That helps in every version.</p></div><p><strong>See also:</strong></p><ul><li><a href="./../anleitungen/effekte-und-presets#numbers-names-effects-palettes-scripts">Where do I find the numbers and names of effects and palettes for scripts?</a></li><li><a href="./../anleitungen/vis-und-smarthome#choose-effect-palette-vis-as">How do I choose the effect and the palette in VIS as a drop-down?</a></li></ul>',37)])])}const k=i(d,[["render",h]]);export{C as __pageData,k as default};
